True def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    from collections import Counter
    background = Counter(v for row in g for v in row).most_common(1)[0][0]
    # Matching cells on a diagonal define a straight ray in both directions.
    # Extend into background cells, stopping at a different colored marker.
    pairs = []
    for r in range(h):
        for c in range(w):
            color = g[r][c]
            if color == background:
                continue
            for dr, dc in ((1, 1), (1, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < h and 0 <= nc < w and g[nr][nc] == color:
                    pairs.append((r, c, dr, dc, color))
    for r, c, dr, dc, color in pairs:
        for sign in (-1, 1):
            rr, cc = r, c
            while True:
                rr += sign * dr
                cc += sign * dc
                if not (0 <= rr < h and 0 <= cc < w):
                    break
                if g[rr][cc] != background and g[rr][cc] != color:
                    break
                g[rr][cc] = color
    return g
